        return Err(GraphError::ReleaseInvariant {
            detail: format!(
                "registry `{}` is configured for ecosystem `{}`, not `{}`",
                key.as_str(),
                registry.kind.prefix(),
                target.ecosystem().map_or("none", |ecosystem| ecosystem.prefix())
            ),
